export { default as LineWaves } from './LineWaves.vue';
export { isLineWavesPreset, lineWavesPreset } from './line-waves-presets';
export type { LineWavesLook, LineWavesPreset, LineWavesProps } from './types';

import {
  LINE_WAVES_FRAGMENT,
  LINE_WAVES_MAX_RIPPLES,
  LINE_WAVES_VERTEX,
} from './line-waves-shaders';
import type {
  LineWavesEngine,
  LineWavesProps,
  LineWavesSettings,
} from './types';

const PIXEL_BUDGET = 2.4e6;

interface LinkedProgram {
  program: WebGLProgram;
  uniform: (name: string) => WebGLUniformLocation | null;
}

interface Ripple {
  x: number;
  y: number;
  age: number;
}

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

function parseColor(value: string): number[] {
  const text = String(value || '').trim();
  const hex = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(text)?.[1];
  if (hex) {
    const full =
      hex.length === 3 ? hex.replace(/./g, (digit) => digit + digit) : hex;
    return [0, 2, 4].map(
      (index) => Number.parseInt(full.slice(index, index + 2), 16) / 255,
    );
  }
  const rgb = /^rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)/i.exec(text);
  if (rgb) {
    return [rgb[1], rgb[2], rgb[3]].map((channel) =>
      clamp(Number.parseFloat(channel ?? '0') / 255, 0, 1),
    );
  }
  return [1, 1, 1];
}

export function toLineWavesSettings(props: LineWavesProps): LineWavesSettings {
  return {
    color1: parseColor(props.color1 ?? '#ffffff'),
    color2: parseColor(props.color2 ?? '#ffffff'),
    color3: parseColor(props.color3 ?? '#ffffff'),
    cycleSpeed: props.colorCycleSpeed ?? 1,
    speed: Math.max(0, props.speed ?? 0.3),
    lines: clamp(props.lineCount ?? 72, 2, 400),
    width: clamp(props.lineWidth ?? 1.3, 0.25, 12),
    glow: Math.max(0, props.glow ?? 0.6),
    brightness: Math.max(0, props.brightness ?? 1),
    highlight: clamp(props.highlight ?? 1, 0, 1),
    highlightWidth: clamp(props.highlightWidth ?? 1, 0.2, 5),
    warp: clamp(props.warpIntensity ?? 1, 0, 3),
    scale: clamp(props.warpScale ?? 1, 0.2, 4),
    rotation: ((props.rotation ?? -33) * Math.PI) / 180,
    edge: clamp(props.edgeFade ?? 0, 0, 1),
    mouse: props.enableMouseInteraction ?? true,
    influence: clamp(props.mouseInfluence ?? 2, 0, 3),
    clickRipple: props.clickRipple ?? true,
    intro: props.intro ?? true,
    light: props.lightMode ?? false,
    opacity: clamp(props.opacity ?? 1, 0, 1),
    maxRatio: clamp(props.maxDevicePixelRatio ?? 2, 0.5, 3),
  };
}

function compile(gl: WebGL2RenderingContext, type: number, source: string) {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
  gl.deleteShader(shader);
  return null;
}

function link(gl: WebGL2RenderingContext): LinkedProgram | null {
  const vertex = compile(gl, gl.VERTEX_SHADER, LINE_WAVES_VERTEX);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, LINE_WAVES_FRAGMENT);
  const program = vertex && fragment ? gl.createProgram() : null;
  if (!vertex || !fragment || !program) {
    if (vertex) gl.deleteShader(vertex);
    if (fragment) gl.deleteShader(fragment);
    return null;
  }
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    return null;
  }
  const locations = new Map<string, WebGLUniformLocation | null>();
  const count: number = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
  for (let i = 0; i < count; i++) {
    const info = gl.getActiveUniform(program, i);
    if (info) {
      locations.set(
        info.name.replace(/\[0\]$/, ''),
        gl.getUniformLocation(program, info.name),
      );
    }
  }
  return { program, uniform: (name) => locations.get(name) ?? null };
}

/**
 * Raw WebGL2 renderer for the line field. `playIntro` is false after a
 * context restore so the lines do not draw in a second time.
 */
export function createLineWavesEngine(
  canvas: HTMLCanvasElement,
  getSettings: () => LineWavesSettings,
  isReduced: () => boolean,
  playIntro: boolean,
): LineWavesEngine | null {
  const gl = canvas.getContext('webgl2', {
    alpha: true,
    premultipliedAlpha: true,
    antialias: false,
    depth: false,
    stencil: false,
    powerPreference: 'high-performance',
  });
  const shader = gl ? link(gl) : null;
  const vao = gl?.createVertexArray() ?? null;
  if (!gl || !shader || !vao) return null;

  const size = { width: 1, height: 1, ratio: 1 };
  const pointer = { x: 0, y: 0, inside: false };
  const lens = { x: 0, y: 0, presence: 0, ready: false };
  const ripples: Ripple[] = [];
  const rippleData = new Float32Array(LINE_WAVES_MAX_RIPPLES * 4);
  let time = Math.random() * 60;
  let cycle = 0;
  let reveal = getSettings().intro && !isReduced() && playIntro ? 0 : 1;
  let last = 0;

  const toField = (x: number, y: number): [number, number] => [
    (x - size.width / 2) / size.height,
    (size.height / 2 - y) / size.height,
  ];

  const frame = (now: number) => {
    if (gl.isContextLost()) return false;
    const s = getSettings();
    const reduced = isReduced();
    const dt = last ? clamp((now - last) / 1000, 0, 0.05) : 0;
    last = now;
    time += dt * s.speed * 2.5 * (reduced ? 0.25 : 1);
    cycle += dt * s.speed * s.cycleSpeed * 0.05;
    if (reveal < 1) reveal = Math.min(1, reveal + dt / 1.8);

    const tracking = s.mouse && pointer.inside && !reduced;
    if (tracking) {
      const [x, y] = toField(pointer.x, pointer.y);
      if (!lens.ready) {
        lens.x = x;
        lens.y = y;
        lens.ready = true;
      }
      const follow = 1 - Math.exp(-dt * 10);
      lens.x += (x - lens.x) * follow;
      lens.y += (y - lens.y) * follow;
    }
    const presence = tracking ? 1 : 0;
    lens.presence += (presence - lens.presence) * (1 - Math.exp(-dt * 5));
    if (lens.presence < 0.002 && !tracking) lens.ready = false;

    for (let i = ripples.length - 1; i >= 0; i--) {
      const ripple = ripples[i];
      if (!ripple) continue;
      ripple.age += dt;
      if (ripple.age > 2.6) ripples.splice(i, 1);
    }
    rippleData.fill(0);
    ripples.forEach((ripple, index) => {
      rippleData.set([ripple.x, ripple.y, ripple.age, 1], index * 4);
    });

    const eased = 1 - Math.pow(1 - reveal, 3);
    const u = shader.uniform;
    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.useProgram(shader.program);
    gl.bindVertexArray(vao);
    gl.uniform2f(u('uResolution'), canvas.width, canvas.height);
    gl.uniform1f(u('uPixel'), size.ratio);
    gl.uniform1f(u('uTime'), time);
    gl.uniform1f(u('uLines'), s.lines);
    gl.uniform1f(u('uWidth'), s.width);
    gl.uniform1f(u('uGlow'), s.glow);
    gl.uniform1f(u('uBrightness'), s.brightness);
    gl.uniform1f(u('uHighlight'), s.highlight);
    gl.uniform1f(u('uHighlightWidth'), s.highlightWidth);
    gl.uniform1f(u('uWarp'), s.warp * (0.25 + 0.75 * eased));
    gl.uniform1f(u('uScale'), s.scale);
    gl.uniform1f(u('uRotation'), s.rotation);
    gl.uniform3fv(u('uColor1'), s.color1);
    gl.uniform3fv(u('uColor2'), s.color2);
    gl.uniform3fv(u('uColor3'), s.color3);
    gl.uniform1f(u('uCycle'), cycle);
    gl.uniform1f(u('uEdge'), s.edge);
    gl.uniform4f(
      u('uMouse'),
      lens.x,
      lens.y,
      lens.presence * s.influence * 0.16,
      0.2,
    );
    gl.uniform4fv(u('uRipples'), rippleData);
    gl.uniform1f(u('uReveal'), eased);
    gl.uniform1f(u('uLight'), s.light ? 1 : 0);
    gl.uniform1f(u('uOpacity'), s.opacity);
    gl.drawArrays(gl.TRIANGLES, 0, 3);

    const settling = Math.abs(presence - lens.presence) > 0.002;
    const busy =
      (s.speed > 0 && !reduced) ||
      reveal < 1 ||
      settling ||
      ripples.length > 0 ||
      tracking;
    if (!busy) last = 0;
    return busy;
  };

  return {
    frame,
    resize(cssWidth, cssHeight) {
      const width = Math.max(1, cssWidth);
      const height = Math.max(1, cssHeight);
      const ratio = Math.min(
        window.devicePixelRatio || 1,
        getSettings().maxRatio,
        Math.sqrt(PIXEL_BUDGET / (width * height)),
      );
      const pixelWidth = Math.max(1, Math.round(width * ratio));
      const pixelHeight = Math.max(1, Math.round(height * ratio));
      if (canvas.width !== pixelWidth || canvas.height !== pixelHeight) {
        canvas.width = pixelWidth;
        canvas.height = pixelHeight;
      }
      size.width = width;
      size.height = height;
      size.ratio = pixelWidth / width;
    },
    pointerMove(x, y, inside) {
      pointer.x = x;
      pointer.y = y;
      pointer.inside = inside;
    },
    pointerDown(x, y, inside) {
      if (!inside || !getSettings().clickRipple || isReduced()) return;
      const [fx, fy] = toField(x, y);
      ripples.push({ x: fx, y: fy, age: 0 });
      if (ripples.length > LINE_WAVES_MAX_RIPPLES) ripples.shift();
    },
    pointerLeave() {
      pointer.inside = false;
    },
    resetClock() {
      last = 0;
    },
    dispose() {
      if (gl.isContextLost()) return;
      gl.deleteVertexArray(vao);
      gl.deleteProgram(shader.program);
    },
  };
}

import type { LineWavesLook, LineWavesPreset } from './types';

const LOOK: LineWavesLook = {
  color1: '#ffffff',
  color2: '#ffffff',
  color3: '#ffffff',
  colorCycleSpeed: 1,
  speed: 0.3,
  lineCount: 72,
  lineWidth: 1.3,
  glow: 0.6,
  brightness: 1,
  highlight: 1,
  highlightWidth: 1,
  warpIntensity: 1,
  warpScale: 1,
  rotation: -33,
};

const PRESETS: Record<LineWavesPreset, LineWavesLook> = {
  silk: LOOK,
  gold: { ...LOOK, color1: '#ffd9a0', color2: '#ffb45e', color3: '#fff0d6' },
  arctic: { ...LOOK, color1: '#cfe9ff', color2: '#7cc0ff', color3: '#eef8ff' },
  aurora: { ...LOOK, color1: '#8ff0d0', color2: '#7aa8ff', color3: '#5fd3e6' },
  engraving: { ...LOOK, lineCount: 130, lineWidth: 0.8, glow: 0.25 },
  ribbon: { ...LOOK, lineCount: 34, lineWidth: 3, glow: 0.9 },
  storm: { ...LOOK, speed: 0.55, warpIntensity: 1.6, warpScale: 0.8 },
  calm: { ...LOOK, speed: 0.15, warpIntensity: 0.6, highlightWidth: 1.8 },
};

/** The look of one of the demo presets. */
export function lineWavesPreset(name: LineWavesPreset): LineWavesLook {
  return { ...PRESETS[name] };
}

export function isLineWavesPreset(value: unknown): value is LineWavesPreset {
  return typeof value === 'string' && value in PRESETS;
}

export const LINE_WAVES_MAX_RIPPLES = 4;

export const LINE_WAVES_VERTEX = `#version 300 es
const vec2 corners[3] = vec2[3](vec2(-1.0, -1.0), vec2(3.0, -1.0), vec2(-1.0, 3.0));
void main() {
  gl_Position = vec4(corners[gl_VertexID], 0.0, 1.0);
}`;

export const LINE_WAVES_FRAGMENT = `#version 300 es
precision highp float;
uniform vec2 uResolution;
uniform float uPixel;
uniform float uTime;
uniform float uLines;
uniform float uWidth;
uniform float uGlow;
uniform float uBrightness;
uniform float uHighlight;
uniform float uHighlightWidth;
uniform float uWarp;
uniform float uScale;
uniform float uRotation;
uniform vec3 uColor1;
uniform vec3 uColor2;
uniform vec3 uColor3;
uniform float uCycle;
uniform float uEdge;
uniform vec4 uMouse;
uniform vec4 uRipples[${LINE_WAVES_MAX_RIPPLES}];
uniform float uReveal;
uniform float uLight;
uniform float uOpacity;
out vec4 fragColor;

vec2 rotate(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(c * p.x - s * p.y, s * p.x + c * p.y);
}

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = p - i;
  vec2 w = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), w.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), w.x), w.y);
}

float smootherstep(float edge0, float edge1, float x) {
  float t = clamp((x - edge0) / (edge1 - edge0), 0.0, 1.0);
  return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

float bend(vec2 p, float t) {
  vec2 q = p * 2.0 / uScale;
  float w = 0.6 * sin(q.x * 0.55 + t * 0.4 + 0.6 * sin(q.y * 0.9 - t * 0.28));
  w += 0.21 * sin(q.x * 1.3 - t * 0.33 + q.y * 0.8 + 1.3);
  w += 0.12 * sin(q.y * 2.3 + q.x * 0.9 - t * 0.37 + 0.4);
  return w * uWarp * uScale * 0.46;
}

float river(vec2 p, float y, float t) {
  float drift = 0.7 * (0.18 * sin(p.x * 1.6 - t * 0.33 + 0.7) + 0.1 * sin(p.x * 3.1 + t * 0.21));
  float center = 0.5 * (0.2 * sin(t * 0.17) + 0.08 * sin(t * 0.29 + 1.3));
  float width = 0.13 * uHighlightWidth;
  float near = (y - center - drift) / width;
  float far = (y + 0.22 * sin(t * 0.13 + 2.0) - drift * 0.6 + 0.3) / (width * 0.55);
  return max(exp(-near * near), exp(-far * far) * 0.7);
}

vec3 palette(float x) {
  x = fract(x) * 3.0;
  if (x < 1.0) return mix(uColor1, uColor2, smoothstep(0.0, 1.0, x));
  if (x < 2.0) return mix(uColor2, uColor3, smoothstep(1.0, 2.0, x));
  return mix(uColor3, uColor1, smoothstep(2.0, 3.0, x));
}

void main() {
  float aspect = uResolution.x / uResolution.y;
  vec2 uv = gl_FragCoord.xy / uResolution;
  vec2 p = rotate((gl_FragCoord.xy - 0.5 * uResolution) / uResolution.y, uRotation);
  float t = uTime;

  vec2 mouse = rotate(uMouse.xy, uRotation);
  vec2 toMouse = p - mouse;
  float lens = exp(-dot(toMouse, toMouse) / (uMouse.w * uMouse.w));
  p.y -= (p.y - mouse.y) * lens * uMouse.z;

  float ring = 0.0;
  for (int i = 0; i < ${LINE_WAVES_MAX_RIPPLES}; i++) {
    vec4 ripple = uRipples[i];
    if (ripple.w <= 0.0) continue;
    float x = (length(p - rotate(ripple.xy, uRotation)) - ripple.z * 0.6) / 0.08;
    float fade = exp(-ripple.z * 1.3) * smoothstep(0.0, 0.12, ripple.z);
    float bump = exp(-x * x);
    p.y -= x * bump * 0.07 * fade;
    ring += bump * fade;
  }

  float w = bend(p, t);
  float y = p.y + w;
  float phi = y * uLines;
  float fw = max(fwidth(phi), 1e-5);
  float crowd = smoothstep(0.18, 0.5, fw);

  float fold = smoothstep(1.3, 2.2, fw * uResolution.y / uLines);
  float shimmer = mix(1.0, smoothstep(0.15, 0.85, noise(vec2(y * 1.6 + t * 0.07, p.x * 0.55 - t * 0.22))), 0.5);
  float lit = max(river(p, y, t), fold * 0.9) * shimmer;
  float light = mix(1.0, 0.07 + 0.93 * lit, uHighlight);
  light += (1.0 - light) * min(lens * step(0.0001, uMouse.z) * 0.9 + ring * 0.6, 1.0);

  float dist = abs(fract(phi + 0.5) - 0.5) / fw;
  float width = uWidth * uPixel * (1.0 + mix(1.5, 0.6, uLight) * lit * uHighlight);
  float cover = clamp(min(dist + width * 0.5, 0.5) - max(dist - width * 0.5, -0.5), 0.0, 1.0);
  cover = mix(cover, min(width * fw, 1.0), crowd);
  float halo = exp(-dist / (2.2 * uPixel)) * (1.0 - crowd) * uGlow;
  float thread = mix(1.0, 0.55 + 0.45 * hash(vec2(floor(phi + 0.5), 7.3)), 0.45 * (1.0 - crowd));

  float span = 0.5 * sqrt(aspect * aspect + 1.0);
  float sweep = -span + (2.0 * span + 0.6) * uReveal;
  float reveal = 1.0 - smoothstep(sweep - 0.6, sweep, p.x);

  float edge = 1.0;
  if (uEdge > 0.0) {
    float ex = min(uv.x, 1.0 - uv.x) * aspect;
    float ey = min(uv.y, 1.0 - uv.y);
    edge = smootherstep(0.0, uEdge * 0.5, ex) * smootherstep(0.0, uEdge * 0.5, ey);
  }

  vec3 tint = palette(y * 0.3 + p.x * 0.2 + uCycle);
  float grain = (fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715)))) - 0.5) / 255.0;

  if (uLight > 0.5) {
    float low = min(tint.r, min(tint.g, tint.b));
    float chroma = max(tint.r, max(tint.g, tint.b)) - low;
    vec3 hue = (tint - low) / max(chroma, 1e-3);
    vec3 ink = mix(vec3(0.08), hue * 0.56 + 0.06, smoothstep(0.04, 0.2, chroma));
    float alpha = (cover + halo * 0.35) * thread * light * uBrightness * reveal * edge * 0.78 * uOpacity;
    alpha = clamp(alpha + grain, 0.0, 1.0);
    fragColor = vec4(ink * alpha, alpha);
    return;
  }

  float strength = (cover + halo) * thread * light * uBrightness * reveal * edge;
  vec3 color = clamp(tint * strength * uOpacity, 0.0, 1.0);
  float alpha = max(color.r, max(color.g, color.b));
  color = clamp(color + grain, 0.0, 1.0);
  fragColor = vec4(min(color, vec3(alpha)), alpha);
}`;

export type LineWavesPreset =
  | 'silk'
  | 'gold'
  | 'arctic'
  | 'aurora'
  | 'engraving'
  | 'ribbon'
  | 'storm'
  | 'calm';

export interface LineWavesProps {
  /** First color the lines blend through. */
  color1?: string;
  /** Second color the lines blend through. */
  color2?: string;
  /** Third color the lines blend through. */
  color3?: string;
  /** How fast the colors drift across the lines. 0 keeps them in place. */
  colorCycleSpeed?: number;
  /** How fast the waves flow. 0 freezes them. */
  speed?: number;
  /** Number of lines across the height of the container. */
  lineCount?: number;
  /** Thickness of the lines, in px. */
  lineWidth?: number;
  /** Strength of the soft glow around each line. */
  glow?: number;
  /** Overall brightness of the lines. */
  brightness?: number;
  /** Strength of the band of light that drifts through the lines, from 0 to 1. */
  highlight?: number;
  /** Width of the band of light. Higher values light more lines at once. */
  highlightWidth?: number;
  /** How strongly the lines bend into waves. */
  warpIntensity?: number;
  /** Size of the waves. Higher values give broad, sweeping curves. */
  warpScale?: number;
  /** Angle of the lines, in degrees. */
  rotation?: number;
  /** Fades the lines out toward the edges of the container, from 0 to 1. */
  edgeFade?: number;
  /** The lines spread apart and light up around the cursor. */
  enableMouseInteraction?: boolean;
  /** How strongly the lines react to the cursor. */
  mouseInfluence?: number;
  /** Clicking sends a smooth wave rolling out through the lines. */
  clickRipple?: boolean;
  /** The lines draw in across the container on mount. */
  intro?: boolean;
  /** Draws the lines as ink for light backgrounds. */
  lightMode?: boolean;
  /** Overall opacity, from 0 to 1. */
  opacity?: number;
  /** Highest pixel ratio the canvas renders at. */
  maxDevicePixelRatio?: number;
  class?: string;
}

/** The tunable look shared by the demo presets. */
export interface LineWavesLook {
  color1: string;
  color2: string;
  color3: string;
  colorCycleSpeed: number;
  speed: number;
  lineCount: number;
  lineWidth: number;
  glow: number;
  brightness: number;
  highlight: number;
  highlightWidth: number;
  warpIntensity: number;
  warpScale: number;
  rotation: number;
}

export interface LineWavesDemoParams extends LineWavesLook {
  preset: LineWavesPreset;
  edgeFade: number;
  enableMouseInteraction: boolean;
  mouseInfluence: number;
  clickRipple: boolean;
  intro: boolean;
  lightMode: boolean;
  opacity: number;
}

export interface LineWavesSettings {
  color1: number[];
  color2: number[];
  color3: number[];
  cycleSpeed: number;
  speed: number;
  lines: number;
  width: number;
  glow: number;
  brightness: number;
  highlight: number;
  highlightWidth: number;
  warp: number;
  scale: number;
  rotation: number;
  edge: number;
  mouse: boolean;
  influence: number;
  clickRipple: boolean;
  intro: boolean;
  light: boolean;
  opacity: number;
  maxRatio: number;
}

export interface LineWavesEngine {
  /** Draws one frame. Returns false when the loop can stop. */
  frame: (now: number) => boolean;
  resize: (width: number, height: number) => void;
  /** Pointer position relative to the container, in CSS px from the top-left. */
  pointerMove: (x: number, y: number, inside: boolean) => void;
  pointerDown: (x: number, y: number, inside: boolean) => void;
  pointerLeave: () => void;
  resetClock: () => void;
  dispose: () => void;
}
